package com.finstack.budget.dto;
import com.finstack.budget.*; import java.math.*; import java.time.*; import java.util.*;
public record BudgetResponse(UUID id,String name,LocalDate budgetMonth,BigDecimal totalLimit,int warningThresholdPercent,boolean active,List<CategoryAllocation> categoryLimits,OffsetDateTime createdAt,OffsetDateTime updatedAt){public record CategoryAllocation(UUID categoryId,String categoryName,BigDecimal limit){} public static BudgetResponse from(Budget b){return new BudgetResponse(b.getId(),b.getName(),b.getBudgetMonth(),b.getTotalLimit(),b.getWarningThresholdPercent(),b.isActive(),b.getCategories().stream().map(c->new CategoryAllocation(c.getCategory().getId(),c.getCategory().getName(),c.getCategoryLimit())).toList(),b.getCreatedAt(),b.getUpdatedAt());}}
